<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { api } from './api'
import { isValidatedModelResult } from './modelState'
const config=ref({base_url:'',model:'',enabled:false,allow_external:false,allow_evidence:false,has_key:false,key_hint:''})
const apiKey=ref(''), allowSend=ref(false), analysisId=ref(''), job=ref<any>(null), password=ref(''), busy=ref(false), error=ref(''), notice=ref('')
let timer:ReturnType<typeof setTimeout>|undefined
const running=computed(()=>job.value&&['queued','running'].includes(job.value.status))
const validModelResult=computed(()=>isValidatedModelResult(job.value))
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function load(){config.value=await api.request('/model/config')}
async function save(){const {base_url,model,enabled,allow_external,allow_evidence}=config.value;await api.put('/model/config',{base_url,model,enabled,allow_external,allow_evidence,...(apiKey.value?{api_key:apiKey.value}:{})});apiKey.value='';await load();notice.value='配置已保存；密钥字段已清空，旧密钥不会返回浏览器。'}
async function poll(){if(!job.value)return;try{job.value=await api.request(`/model/jobs/${job.value.id}`);if(running.value)timer=setTimeout(poll,1000)}catch(e){error.value=`轮询失败，任务状态未知：${e instanceof Error?e.message:String(e)}`}}
async function start(purpose:'test'|'explain'){if(timer)clearTimeout(timer);job.value=await api.post('/model/jobs',{purpose,...(purpose==='explain'?{analysis_id:analysisId.value,allow_send:allowSend.value}:{})});await poll()}
async function cancel(){if(!job.value)return;const state=await api.post(`/model/jobs/${job.value.id}/cancel`,{});job.value={...job.value,...state};notice.value='已请求取消；不表示远端立即停止计费。';if(timer)clearTimeout(timer);if(running.value)timer=setTimeout(poll,1000)}
async function backup(){if(password.value.length<12)throw Error('备份密码至少12字符');const blob=await api.post<Blob>('/backup',{password:password.value});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`tcm-encrypted-backup-${new Date().toISOString().slice(0,10)}.tcmbak`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);password.value='';notice.value='已发起加密备份下载。请妥善保管密码，恢复仅支持空目标目录。'}
onMounted(()=>run(load));onUnmounted(()=>{if(timer)clearTimeout(timer)})
</script>
<template><section aria-label="模型与备份"><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="notice" :title="notice" type="success" :closable="false"/><div class="settings-grid"><div class="panel"><h2>可选模型辅助</h2><p class="hint">默认禁止外发。模型只提出补充解释，不修改事实、规则或医生决定。</p><label>API 基址<input v-model="config.base_url" type="url" placeholder="HTTPS 或 HTTP loopback" :disabled="busy"></label><label>模型名<input v-model="config.model" :disabled="busy"></label><label>新 API 密钥（留空保留现有）<input v-model="apiKey" type="password" autocomplete="new-password" :disabled="busy"></label><p class="hint">{{config.has_key?`已保存密钥 · ${config.key_hint||'••••'}`:'尚未保存密钥'}}</p><label class="check"><input type="checkbox" v-model="config.enabled" :disabled="busy">启用模型服务</label><label class="check"><input type="checkbox" v-model="config.allow_external" :disabled="busy">允许向配置服务发送限定的非身份结构化数据</label><label class="check"><input type="checkbox" v-model="config.allow_evidence" :disabled="busy||!config.allow_external">额外允许发送该分析关联的资料原文证据</label><el-button type="primary" :loading="busy" @click="run(save)">保存配置</el-button><hr><h3>连通与补充分析</h3><p class="hint">连接测试只发送固定合成文本。补充分析不会发送病例代号、备注、主诉或事实原始描述。</p><el-button :disabled="busy||running" @click="run(()=>start('test'))">用固定合成文本测试连接</el-button><label>已存分析 ID<input v-model="analysisId" placeholder="从接诊分析记录复制ID" :disabled="busy||running"></label><label class="check"><input type="checkbox" v-model="allowSend" :disabled="busy||running">本次明确允许发送已保存分析的限定数据</label><div class="button-row"><el-button :disabled="busy||running||!allowSend||!analysisId||!config.allow_external" @click="run(()=>start('explain'))">请求模型补充分析</el-button><el-button type="danger" plain :disabled="busy||!running" @click="run(cancel)">取消任务</el-button><el-button v-if="job" :disabled="busy" @click="run(poll)">刷新任务状态</el-button></div><article v-if="job" class="model-box"><div class="section-head"><h3>模型{{validModelResult?'补充（已校验）':'文本预览 · 非正式结果'}}</h3><el-tag :type="validModelResult?'success':'warning'">{{job.status}}</el-tag></div><small>{{job.id}}</small><pre>{{job.text||'尚无输出'}}</pre><p v-if="job.error" class="warning">{{job.error}}</p><pre v-if="job.usage">用量：{{JSON.stringify(job.usage,null,2)}}</pre><p class="warning" v-if="!validModelResult">部分输出、失败、取消及未校验完成文本均不能作为正式补充结果。</p></article></div><div class="panel"><h2>加密备份</h2><p>备份包括数据库、登记原件及哈希清单。模型密钥不进入备份。</p><label>备份密码（至少12字符）<input v-model="password" type="password" minlength="12" autocomplete="new-password" :disabled="busy"></label><el-button type="primary" :loading="busy" :disabled="password.length<12" @click="run(backup)">下载加密备份</el-button><p class="hint">密码无法找回。恢复使用本地恢复工具，目标目录必须为空；浏览器不覆盖当前病历。</p><hr><h3>当前边界</h3><p class="hint">工程验证 · 模拟病例。真实病例持久化、专业适用范围和安全资料覆盖须另行验证。真实模型连接需有效凭据及供应商权限。</p></div></div></section></template>
